DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.activate_contract(uuid,text)'::regprocedure) INTO d;d:=replace(d,'part:=CASE WHEN n=p.installments_count THEN rent-rentdone ELSE round(rent/p.installments_count,2) END;','part:=trunc(rent*100/p.installments_count)/100+CASE WHEN n>p.installments_count-mod(rent*100,p.installments_count) THEN 0.01 ELSE 0 END;');d:=replace(d,'taxpart:=CASE WHEN n=p.installments_count THEN tax-taxdone ELSE round(tax/p.installments_count,2) END;','taxpart:=trunc(tax*100/p.installments_count)/100+CASE WHEN n>p.installments_count-mod(tax*100,p.installments_count) THEN 0.01 ELSE 0 END;');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.finance_safety_regression_tests() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid();party uuid;uid uuid;plan uuid;c uuid;r uuid;i uuid;rejected boolean;result jsonb;BEGIN IF NOT public.has_role(actor,'admin') THEN RAISE EXCEPTION 'اختبار الأدمن فقط';END IF;BEGIN SELECT id INTO party FROM public.parties WHERE archived_at IS NULL AND merged_into_id IS NULL LIMIT 1;SELECT id INTO uid FROM public.units WHERE leasing_status='available' AND NOT is_test AND NOT EXISTS(SELECT 1 FROM public.tenants WHERE unit_id=units.id AND archived_at IS NULL) LIMIT 1;IF party IS NULL OR uid IS NULL THEN RAISE EXCEPTION 'بيانات اختبار متاحة مطلوبة';END IF;
plan:=public.save_payment_plan(NULL,'اختبار مالي معزول',1,1,NULL,'اختبار شروط التأجير');c:=public.create_contract(jsonb_build_object('contract_no','TEST-'||gen_random_uuid(),'party_id',party,'start_date',current_date,'end_date',current_date+365,'annual_rent_excl_vat',100,'vat_rate',15,'payment_plan_id',plan,'signed_at',now(),'units',jsonb_build_array(jsonb_build_object('unit_id',uid,'rent',100))),'اختبار عقد قابل للتراجع');PERFORM public.activate_contract(c,'تفعيل اختبار مالي');INSERT INTO public.unit_status_write_capabilities VALUES(txid_current(),uid) ON CONFLICT DO NOTHING;UPDATE public.units SET leasing_status='pending_contract' WHERE id=uid;DELETE FROM public.unit_status_write_capabilities WHERE transaction_id=txid_current() AND unit_id=uid;
rejected:=false;BEGIN PERFORM public.set_unit_status(uid,'leased','اختبار رفض تأجير الأدمن','contract',c);EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'الأدمن تجاوز شرط مدير التأجير';END IF;
INSERT INTO public.user_roles(user_id,role,is_active) VALUES(actor,'leasing_manager',true) ON CONFLICT(user_id,role) DO UPDATE SET is_active=true;rejected:=false;BEGIN PERFORM public.set_unit_status(uid,'leased','اختبار رفض نقص الدفعة','contract',c);EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'تم التأجير دون الدفعة';END IF;
SELECT id INTO i FROM public.installments WHERE contract_id=c AND sequence_no=1;r:=public.record_receipt(jsonb_build_object('party_id',party,'contract_id',c,'paid_at',now(),'method','test','amount_excl_vat',100,'vat_amount',15,'idempotency_key',gen_random_uuid()),'تسجيل دفعة اختبار');PERFORM public.allocate_receipt(r,i,100,15,'تخصيص دفعة اختبار');rejected:=false;BEGIN PERFORM public.set_unit_status(uid,'leased','اختبار رفض إيصال غير متحقق','contract',c);EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'تم التأجير قبل التحقق';END IF;PERFORM public.verify_receipt(r,'تحقق دفعة اختبار');PERFORM public.set_unit_status(uid,'leased','تأكيد مدير التأجير المعزول','contract',c);IF(SELECT leasing_status FROM public.units WHERE id=uid)<>'leased' THEN RAISE EXCEPTION 'فشل التأجير اليدوي';END IF;
PERFORM public.reverse_receipt(r,'عكس دفعة الاختبار');PERFORM public.waive_installment(i,'إعفاء بعد عكس كامل');IF(SELECT status FROM public.installments WHERE id=i)<>'waived' THEN RAISE EXCEPTION 'فشل الإعفاء بعد العكس';END IF;
rejected:=false;BEGIN UPDATE public.unit_collections SET amount=amount WHERE id=(SELECT id FROM public.unit_collections LIMIT 1);EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'السجل القديم قابل للتعديل';END IF;
result:=jsonb_build_object('admin_cannot_lease',true,'first_payment_required',true,'verification_required',true,'manual_leasing_manager_confirmed',true,'waiver_after_reversal',true,'legacy_readonly',true);RAISE EXCEPTION 'ROLLBACK_FINANCE_SAFETY' USING ERRCODE='P0002';EXCEPTION WHEN SQLSTATE 'P0002' THEN RETURN result;END;END $$;
REVOKE ALL ON FUNCTION public.finance_safety_regression_tests() FROM PUBLIC,anon,service_role;GRANT EXECUTE ON FUNCTION public.finance_safety_regression_tests() TO authenticated;
SELECT exists(SELECT 1 FROM pg_proc WHERE proname='finance_safety_regression_tests') AS safety_test_available;